#include <iostream>
using namespace std;

using ull = long long;

ull n;

bool tr(ull k) {
    ull taken = 0;
    ull remaining = n;
    const ull target = (n - 1) / 2 + 1;

    while (remaining > 0) {
        ull current = min(k, remaining);
        taken += current;
        remaining -= current;
        remaining -= remaining / 10;

        if (taken >= target)
            return true;
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    ull left = 1, right = n;
    while (left < right) {
        ull middle = left + (right - left) / 2;
        if (tr(middle))
            right = middle;
        else
            left = middle + 1;
    }

    cout << left << '\n';
    return 0;
}

